-- Agreed tests (verification step 2, plain SQL on PostgreSQL) for WideWorldImporters Website.Suppliers.
-- GENERATED by npm run agreed-tests -- --object Website.Suppliers. Do not edit by hand: change the fixed cases
-- in the object's spec, recapture, and review tests/WideWorldImporters/Website.Suppliers.expected.json.
-- Expected results were captured from the original T-SQL on SQL Server and are reviewed at step 5.
-- Row order is not asserted here (multiset comparison); step 3 checks order where the source guarantees one.
-- Prerequisites: the spec's tables created and the final conversion deployed.
-- Each case is one transaction and always rolls back.

-- @case 1: LEFT JOINs keep every supplier: missing category, contacts or city, and a NULL delivery method, give NULL; same person as both contacts; geography as WKT; '' and NULL kept apart
BEGIN;
DELETE FROM purchasing.suppliers;
DELETE FROM purchasing.supplier_categories;
DELETE FROM application.people;
DELETE FROM application.delivery_methods;
DELETE FROM application.cities;
INSERT INTO purchasing.suppliers ("SupplierID", "SupplierName", "SupplierCategoryID", "PrimaryContactPersonID", "AlternateContactPersonID", "DeliveryMethodID", "DeliveryCityID", "SupplierReference", "PhoneNumber", "FaxNumber", "WebsiteURL", "DeliveryLocation") VALUES
  ('1', 'Supplier 1', '1', '1', '2', NULL, '1', '', '(415) 555-0100', '(415) 555-0101', 'http://s1.example.com', 'POINT(-0.25 51.5)'),
  ('2', 'Supplier 2', '99', '98', '99', NULL, '99', NULL, '(415) 555-0100', '(415) 555-0101', 'http://s2.example.com', NULL),
  ('3', 'Supplier 3', '1', '1', '1', '1', '1', 'REF-3', '(415) 555-0100', '(415) 555-0101', 'http://s3.example.com', 'POINT(174.75 -36.75)');
INSERT INTO purchasing.supplier_categories ("SupplierCategoryID", "SupplierCategoryName") VALUES
  ('1', 'Toy Supplier');
INSERT INTO application.people ("PersonID", "FullName") VALUES
  ('1', 'Ann Lee'),
  ('2', 'Bo Ng');
INSERT INTO application.delivery_methods ("DeliveryMethodID", "DeliveryMethodName") VALUES
  ('1', 'Air Freight');
INSERT INTO application.cities ("CityID", "CityName") VALUES
  ('1', 'Auckland');
CREATE TEMP TABLE pp_actual ON COMMIT DROP AS
SELECT "SupplierID", "SupplierName", "SupplierCategoryName", "PrimaryContact", "AlternateContact", "PhoneNumber", "FaxNumber", "WebsiteURL", "DeliveryMethod", "CityName", ST_AsText("DeliveryLocation") AS "DeliveryLocation", "SupplierReference" FROM website.suppliers;
DO $pp$
DECLARE got text[];
BEGIN
  SELECT array_agg(attname::text ORDER BY attnum) INTO got FROM pg_attribute WHERE attrelid = 'pp_actual'::regclass AND attnum > 0 AND NOT attisdropped;
  IF got IS DISTINCT FROM ARRAY['SupplierID', 'SupplierName', 'SupplierCategoryName', 'PrimaryContact', 'AlternateContact', 'PhoneNumber', 'FaxNumber', 'WebsiteURL', 'DeliveryMethod', 'CityName', 'DeliveryLocation', 'SupplierReference']::text[] THEN
    RAISE EXCEPTION 'agreed test failed (%): columns are %, expected %', 'test 01 LEFT JOINs keep every supplier: missing category, contacts or city, and a NULL delivery method, give…', got, ARRAY['SupplierID', 'SupplierName', 'SupplierCategoryName', 'PrimaryContact', 'AlternateContact', 'PhoneNumber', 'FaxNumber', 'WebsiteURL', 'DeliveryMethod', 'CityName', 'DeliveryLocation', 'SupplierReference']::text[];
  END IF;
END $pp$;
CREATE TEMP TABLE pp_expected (LIKE pp_actual) ON COMMIT DROP;
INSERT INTO pp_expected VALUES
  ('1', 'Supplier 1', 'Toy Supplier', 'Ann Lee', 'Bo Ng', '(415) 555-0100', '(415) 555-0101', 'http://s1.example.com', NULL, 'Auckland', 'POINT(-0.25 51.5)', ''),
  ('2', 'Supplier 2', NULL, NULL, NULL, '(415) 555-0100', '(415) 555-0101', 'http://s2.example.com', NULL, NULL, NULL, NULL),
  ('3', 'Supplier 3', 'Toy Supplier', 'Ann Lee', 'Ann Lee', '(415) 555-0100', '(415) 555-0101', 'http://s3.example.com', 'Air Freight', 'Auckland', 'POINT(174.75 -36.75)', 'REF-3');
DO $pp$
DECLARE missing bigint; extra bigint;
BEGIN
  SELECT count(*) INTO missing FROM ((SELECT * FROM pp_expected) EXCEPT ALL (SELECT * FROM pp_actual)) AS d;
  SELECT count(*) INTO extra FROM ((SELECT * FROM pp_actual) EXCEPT ALL (SELECT * FROM pp_expected)) AS d;
  IF missing > 0 OR extra > 0 THEN
    RAISE EXCEPTION 'agreed test failed (%): % expected row(s) missing, % unexpected row(s) in the result', 'test 01 LEFT JOINs keep every supplier: missing category, contacts or city, and a NULL delivery method, give…', missing, extra;
  END IF;
END $pp$;
ROLLBACK;
